/*
 * A119892  Prime quartet leaders: largest number of a prime quartet.
 * https://oeis.org/A119892
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, nonn
 * Formula:   not stated
 * Range:     u8 none, u16 n <= 283, u32 n <= 2000, u64 n <= 2000,
 *            u128 n <= 2000, big any n
 * Helpers:   digit_sum, grow_seq, is_prime_small
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence: Prime quartet leaders – largest prime in a prime quartet.
 * The sequence is generated by testing primes for the property that
 * digit_sum(p1) is prime, digit_sum(digit_sum(p1)) is prime and
 * digit_sum(digit_sum(digit_sum(p1))) is a single‑digit prime (2,3,5,7).
 * All four primes must be distinct.
 */

#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

#include "../utils/grow_seq.h"
#include "../utils/is_prime_small.h"
#include "../utils/digit_sum.h"

static const idx_t LIMIT = 10000000;     /* sufficient for n ≤ 10000 */
static bool initialized = false;

static uint64_t *prime_nums   = NULL;   /* array of primes ≤ LIMIT   */
static idx_t     prime_count  = 0;      /* number of primes generated */

static seq_t *quartet_leaders = NULL;   /* collected sequence terms   */
static size_t term_count      = 0;
static size_t term_cap        = 0;
static idx_t  prime_pos       = 0;      /* next prime to test         */

/* Construct the sieve of Eratosthenes once, then collect the primes. */
static void init_primes(void)
{
    bool *sieve = (bool *)malloc((size_t)(LIMIT + 1));
    if (!sieve) exit(1);          /* malloc failed */

    for (size_t i = 0; i <= LIMIT; ++i) sieve[i] = true;
    sieve[0] = sieve[1] = false;

    for (uint32_t i = 2; (uint64_t)i * i <= LIMIT; ++i)
        if (sieve[i])
            for (uint64_t j = (uint64_t)i * i; j <= LIMIT; j += i)
                sieve[j] = false;

    /* Count primes first to allocate the exact size. */
    for (uint32_t i = 2; i <= LIMIT; ++i) if (sieve[i]) ++prime_count;

    prime_nums = (uint64_t *)malloc(prime_count * sizeof(uint64_t));
    if (!prime_nums) exit(1);

    idx_t idx = 0;
    for (uint32_t i = 2; i <= LIMIT; ++i)
        if (sieve[i]) prime_nums[idx++] = i;

    free(sieve);
}

/* Test whether a prime satisfies the quartet condition. */
static bool is_good_prime(seq_t p)
{
    seq_t s1 = digit_sum(p);
    if (!is_prime_small(s1)) return false;

    seq_t s2 = digit_sum(s1);
    if (!is_prime_small(s2)) return false;

    seq_t s3 = digit_sum(s2);
    if (!(s3 == 2 || s3 == 3 || s3 == 5 || s3 == 7)) return false;

    /* all four primes must be distinct – only need to check the last two */
    if (s2 == s3) return false;
    return true;
}

/* Generate terms until we have at least 'need' elements. */
static void generate_terms(idx_t need)
{
    while (term_count < need && prime_pos < prime_count) {
        uint64_t pv = prime_nums[prime_pos++];
        if (is_good_prime((seq_t)pv)) {
            grow_seq(&quartet_leaders, &term_cap, term_count + 1);
            quartet_leaders[term_count++] = (seq_t)pv;
        }
    }
    /* For n ≤ 10000 the limit is sufficient; no further extension needed. */
}

seq_t a(idx_t n)
{
    if (!initialized) {
        init_primes();
        initialized = true;
    }
    if (n == 0) return 0;          /* sequence is 1‑indexed; caller should avoid 0 */
    if (n > term_count) generate_terms(n);
    return quartet_leaders[n - 1];
}
